    add.u32         %r_tmp2, %r_tmp2, %r_kh;
    mul.lo.u32      %r_tmp2, %r_tmp2, %r_KW;
    add.u32         %r_tmp2, %r_tmp2, %r_kw;
    mul.wide.u32    %rd_off_wt, %r_tmp2, 2;

