        self.output_padding = output_padding
        self.groups = groups
        self.bias = bias

        # weight tensor in fp16 matching PyTorch ConvTranspose2d layout
        self.weight = torch.nn.Parameter(
            torch.randn(
                out_channels,
                in_channels // groups,
                kernel_size,
                kernel_size,
                dtype=torch.float16,
                device='cuda'
            )
        )
        if bias:
            self.bias_param = torch.nn.Parameter(
                torch.randn(out_channels, dtype=torch.float16, device='cuda')
            )
        else:
            self.register_parameter('bias_param', None)

        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure fp16
        x = x.to(dtype=torch.float16, device='cuda')
        batch, _, H_in, W_in = x.shape
        K = self.kernel_size
        S = self.stride
        P = self.padding
        OP = self.output_padding
        G = self.groups

        # compute output dimensions (same as torch.nn.ConvTranspose2d)
        H_out = (H_in - 1) * S - 2 * P + K + OP
        W_out = (W_in - 1) * S - 2 * P + K + OP

        out = torch.empty(
            batch,
            self.out_channels,
            H_out,
            W_out,
            dtype=torch.float16,
            device='cuda'
        )

        # launch configuration (1D grid)
        total = batch * self.out_channels * H_out * W_out
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            out.data_ptr(),
            batch,
            self.in_channels,
            self.out_channels,
            H_in,
            W_in,
            H_out,
            W_out,
            K,          # KH
            K,          # KW (square kernel)
            S,          # stride
            P,          # padding
            G           # groups
        ]

        ptx_launch(self.module, "conv_transpose2d_fp16", grid, (block, 1, 1), args)

        if self.bias:
            out = out + self.bias_param.view(1, -1, 1, 1)

        return out
